begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id,email_confirmed_at) values (md5('cardio_a')::uuid,clock_timestamp()),(md5('cardio_b')::uuid,clock_timestamp());
insert into profiles(id,display_name) values(md5('cardio_a')::uuid,'Cardio A'),(md5('cardio_b')::uuid,'Cardio B');
insert into account_preferences(owner_id) values(md5('cardio_a')::uuid),(md5('cardio_b')::uuid);
select set_config('request.jwt.claims',json_build_object('sub',md5('cardio_a')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select set_config('c.w',start_ad_hoc_workout()::text,true);
select set_config('c.item',gen_random_uuid()::text,true);
select set_config('c.request',gen_random_uuid()::text,true);
select lives_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'add',0,'treadmill',null,current_setting('c.request')::uuid)$$,'pending treadmill belongs to actual session');
select is(jsonb_array_length(workout_cardio_items(current_setting('c.w')::uuid)),1,'one cardio item');
select is(workout_cardio_items(current_setting('c.w')::uuid)->0->'durationSeconds','null'::jsonb,'no duration is invented');
select is((select count(*)::int from workout_exercises where workout_session_id=current_setting('c.w')::uuid),0,'cardio creates no exercise selections');
select is((select count(*)::int from workout_sets where owner_id=auth.uid()),0,'cardio creates no fake strength sets');
select set_config('c.activity',(select last_activity_at::text from workout_sessions where id=current_setting('c.w')::uuid),true);
select lives_ok($$select set_workout_pause(current_setting('c.w')::uuid,true,0,gen_random_uuid())$$,'pause before passive cardio receipt retry');
select lives_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'add',0,'treadmill',null,current_setting('c.request')::uuid)$$,'exact add retry is idempotent');
select ok((select manual_paused_at is not null from workout_sessions where id=current_setting('c.w')::uuid),'receipt retry never resumes manual pause');
select is((select last_activity_at::text from workout_sessions where id=current_setting('c.w')::uuid),current_setting('c.activity'),'receipt retry does not alter timer activity');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'add',0,'bike',null,current_setting('c.request')::uuid)$$,'23514',null,'request UUID cannot change intent');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',1,'treadmill',0,gen_random_uuid())$$,'22023',null,'zero duration rejected');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',1,'treadmill',-1,gen_random_uuid())$$,'22023',null,'negative duration rejected');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',1,'treadmill',86401,gen_random_uuid())$$,'22023',null,'oversized duration rejected');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',1,'hiit',1200,gen_random_uuid())$$,'22023',null,'unapproved activity rejected');
select set_config('c.save',gen_random_uuid()::text,true);
select lives_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',1,'treadmill',1200,current_setting('c.save')::uuid)$$,'actual manual duration saved');
select ok((select manual_paused_at is null from workout_sessions where id=current_setting('c.w')::uuid),'new saved cardio resumes through existing activity authority');
select is((select jsonb_array_length(manual_pause_intervals) from workout_sessions where id=current_setting('c.w')::uuid),1,'cardio preserves one actual pause interval');
select is((workout_cardio_items(current_setting('c.w')::uuid)->0->>'durationSeconds')::int,1200,'20 minutes is exact duration evidence');
select lives_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',1,'treadmill',1200,current_setting('c.save')::uuid)$$,'uncertain save retry returns the same committed result');
select is((select count(*)::int from workout_cardio_commands where workout_session_id=current_setting('c.w')::uuid),2,'retry does not duplicate evidence');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',1,'treadmill',1300,gen_random_uuid())$$,'40001',null,'stale revision cannot overwrite another device');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',2,'bike',1300,gen_random_uuid())$$,'23514',null,'canonical activity cannot silently change');
select is((select cardio_seconds::int from workout_cardio_summary(array[current_setting('c.w')::uuid])),1200,'bounded summary uses latest actual duration');
select throws_ok($$update workout_cardio_commands set duration_seconds=30$$,'42501',null,'raw evidence edits denied');
select throws_ok($$delete from workout_cardio_commands$$,'42501',null,'raw evidence deletion denied');
select throws_ok($$insert into workout_cardio_commands(request_id,workout_session_id,item_id,operation,expected_revision,activity,duration_seconds,revision) values(gen_random_uuid(),current_setting('c.w')::uuid,gen_random_uuid(),'add',0,'bike',null,88)$$,'42501',null,'derived revisions cannot be supplied');
select set_config('request.jwt.claims',json_build_object('sub',md5('cardio_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from workout_cardio_commands),0,'foreign cardio evidence hidden');
select throws_ok($$select workout_cardio_items(current_setting('c.w')::uuid)$$,'42501',null,'foreign detail read denied');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',2,'treadmill',1400,gen_random_uuid())$$,'42501',null,'foreign session mutation denied');
select is((select count(*)::int from workout_cardio_summary(array[current_setting('c.w')::uuid])),0,'foreign summary reveals no private duration');
select set_config('c.foreign',start_ad_hoc_workout()::text,true);
select set_config('request.jwt.claims',json_build_object('sub',md5('cardio_a')::uuid,'role','authenticated')::text,true);
select throws_ok($$select record_workout_cardio(current_setting('c.foreign')::uuid,current_setting('c.item')::uuid,'save',2,'treadmill',1400,gen_random_uuid())$$,'42501',null,'item cannot be transferred across sessions');
select lives_ok($$select end_workout(current_setting('c.w')::uuid,'completed')$$,'cardio-only session closes through ordinary workflow');
select is((select count(*)::int from workout_history('incomplete') where id=current_setting('c.w')::uuid),0,'finished cardio-only workout is not mislabeled incomplete');
select is((select working_sets::int from workout_training_summary(array[current_setting('c.w')::uuid])),0,'cardio never counts as qualifying strength work');
select is((select count(*)::int from performance_source(null,null,null,null) where session_id=current_setting('c.w')::uuid),0,'no strength performance/PR source manufactured');
select throws_ok($$select record_workout_cardio(current_setting('c.w')::uuid,current_setting('c.item')::uuid,'save',2,'treadmill',1400,gen_random_uuid())$$,'23514',null,'closed session rejects duration corrections');
select lives_ok($$select retain_workout(current_setting('c.w')::uuid,'archive',gen_random_uuid(),0)$$,'archive retains cardio evidence');
select is((workout_cardio_items(current_setting('c.w')::uuid)->0->>'durationSeconds')::int,1200,'archived original duration remains readable');
select lives_ok($$select retain_workout(current_setting('c.w')::uuid,'restore',gen_random_uuid(),1)$$,'restore uses retained evidence without replay');
select is((select count(*)::int from workout_cardio_commands where workout_session_id=current_setting('c.w')::uuid),2,'restore never duplicates duration');
select lives_ok($$select retain_workout(current_setting('c.w')::uuid,'delete',gen_random_uuid(),2)$$,'permanent parent deletion removes cardio evidence');
select is((select count(*)::int from workout_cardio_commands where workout_session_id=current_setting('c.w')::uuid),0,'no orphan duration facts remain');
-- Cardio does not satisfy scheduled program positions or pending lifecycle ends.
select set_config('c.version',(select id::text from program_versions where definition->'program'->>'slug'='full-body-foundation'),true);
select set_config('c.assignment',(program_lifecycle('start',gen_random_uuid(),null,0,current_setting('c.version')::uuid,current_date,'UTC')->>'assignmentId'),true);
select lives_ok($$select program_lifecycle('end_after_next',gen_random_uuid(),current_setting('c.assignment')::uuid,(select lifecycle_revision from program_assignments where id=current_setting('c.assignment')::uuid))$$,'pending program end recorded against exact assignment');
select set_config('c.program',start_program_workout(current_setting('c.version')::uuid,1,gen_random_uuid())::text,true);
select set_config('c.pi',gen_random_uuid()::text,true);
select lives_ok($$select record_workout_cardio(current_setting('c.program')::uuid,current_setting('c.pi')::uuid,'add',0,'outdoor_run',null,gen_random_uuid())$$,'cardio can accompany a prescribed workout');
select lives_ok($$select record_workout_cardio(current_setting('c.program')::uuid,current_setting('c.pi')::uuid,'save',1,'outdoor_run',900,gen_random_uuid())$$,'real cardio duration in program session');
select lives_ok($$select end_workout(current_setting('c.program')::uuid,'completed')$$,'program session can close without invented strength');
select is((select completion_status from workout_program_classifications(array[current_setting('c.program')::uuid])),'none','cardio does not satisfy prescribed work');
select is((select state from program_assignments where id=current_setting('c.assignment')::uuid),'active','cardio alone cannot end a program');
select ok((select pending_end_request_id is not null from program_assignments where id=current_setting('c.assignment')::uuid),'pending end remains pending after cardio-only closure');
select is((select count(*)::int from program_schedule_resolutions(current_setting('c.assignment')::uuid)),0,'cardio does not resolve any required program position');

-- All five activity types and the live-item resource cap use the same authority.
select set_config('c.limitworkout',start_ad_hoc_workout()::text,true);
do $$declare i int;k text;begin for i in 1..20 loop k:=(array['treadmill','outdoor_run','elliptical','bike','stationary_bike'])[(i-1)%5+1];perform record_workout_cardio(current_setting('c.limitworkout')::uuid,gen_random_uuid(),'add',0,k,null,gen_random_uuid());end loop;end $$;
select is(jsonb_array_length(workout_cardio_items(current_setting('c.limitworkout')::uuid)),20,'all supported activities can be added as real pending items');
select throws_ok($$select record_workout_cardio(current_setting('c.limitworkout')::uuid,gen_random_uuid(),'add',0,'bike',null,gen_random_uuid())$$,'23514',null,'21st live item denied atomically');
select set_config('c.remove',(workout_cardio_items(current_setting('c.limitworkout')::uuid)->0->>'id'),true);
select set_config('c.kind',(workout_cardio_items(current_setting('c.limitworkout')::uuid)->0->>'activity'),true);
select lives_ok($$select record_workout_cardio(current_setting('c.limitworkout')::uuid,current_setting('c.remove')::uuid,'save',1,current_setting('c.kind'),60,gen_random_uuid())$$,'pending item can receive exact duration');
select lives_ok($$select record_workout_cardio(current_setting('c.limitworkout')::uuid,current_setting('c.remove')::uuid,'remove',2,current_setting('c.kind'),null,gen_random_uuid())$$,'explicit removal preserves independent strength evidence');
select is((select cardio_seconds::int from workout_cardio_summary(array[current_setting('c.limitworkout')::uuid])),0,'removed duration no longer contributes to current summary');
select throws_ok($$select record_workout_cardio(current_setting('c.limitworkout')::uuid,current_setting('c.remove')::uuid,'save',3,current_setting('c.kind'),60,gen_random_uuid())$$,'42501',null,'removed item cannot silently be resurrected');
select throws_ok($$select workout_cardio_summary(array_fill(current_setting('c.limitworkout')::uuid,array[52]))$$,'22023',null,'history summary requests remain bounded');
set local role authenticated;
select lives_ok($$select end_workout(current_setting('c.limitworkout')::uuid,'abandoned')$$,'pending cardio can be deliberately abandoned without completion');
select set_config('c.expired',start_ad_hoc_workout()::text,true);
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '15 hours',last_activity_at=clock_timestamp()-interval '13 hours',activity_evidence_at=clock_timestamp()-interval '13 hours' where id=current_setting('c.expired')::uuid;
set local role authenticated;
select is(record_workout_cardio(current_setting('c.expired')::uuid,gen_random_uuid(),'add',0,'bike',null,gen_random_uuid()),null::jsonb,'expired cardio write returns no false acknowledgement');
select is((select status from workout_sessions where id=current_setting('c.expired')::uuid),'abandoned','lazy expiry commits authoritative closure');
select is((select count(*)::int from workout_cardio_commands where workout_session_id=current_setting('c.expired')::uuid),0,'expired request creates no fictional duration or structure');
select ok(not has_table_privilege(r,'public.workout_cardio_commands','UPDATE,DELETE'),'immutable facts for '||r) from unnest(array['anon','authenticated','service_role'])r;
select ok(not has_function_privilege(r,f,'EXECUTE'),'no anonymous/service cardio RPC: '||f) from unnest(array['anon','service_role'])r cross join unnest(array['public.workout_cardio_items(uuid)','public.record_workout_cardio(uuid,uuid,text,bigint,text,integer,uuid)','public.workout_cardio_summary(uuid[])'])f;
select * from finish();rollback;
